if mibBuilder.loadTexts: cwdxQosCtrlUpMaxRsvdBWPercent.setReference('Data-Over-Cable Service Interface Specifications (DOCSIS)\n             Radio Frequency Interface Specification \n             (SP-RFI-I04-980724). section 6.4 and appendix C.')
